package com.shopstream.notification.chat;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.listener.PatternTopic;
import org.springframework.data.redis.listener.RedisMessageListenerContainer;
import org.springframework.messaging.simp.SimpMessagingTemplate;

@Configuration
public class ChatConfig {

    @Bean
    RedisMessageListenerContainer chatContainer(RedisConnectionFactory factory,
                                                SimpMessagingTemplate websocket) {
        RedisMessageListenerContainer container = new RedisMessageListenerContainer();
        container.setConnectionFactory(factory);
        container.addMessageListener((message, pattern) -> {
            String channel = new String(message.getChannel());
            String roomId = channel.substring(channel.lastIndexOf(':') + 1);
            String body = new String(message.getBody());
            websocket.convertAndSend("/topic/rooms." + roomId, body);
        }, new PatternTopic("chat:room:*"));
        return container;
    }
}

package com.shopstream.assistant;
import java.util.Optional;
public class SemanticCache {
    interface Embedder { float[] embed(String text); }
    interface VectorIndex {
        Optional<Hit> nearest(float[] vector);
        void put(String question, float[] vector, String answer, long ttlSeconds);
    }
    record Hit(String answer, double distance) {}

    private static final double MAX_DISTANCE = 0.12;   // tune on real data
    private static final long TTL_SECONDS = 24 * 3600;

    private final Embedder embedder;
    private final VectorIndex index;

    public SemanticCache(Embedder embedder, VectorIndex index) {
        this.embedder = embedder;
        this.index = index;
    }

    public String answer(String question, java.util.function.Function<String, String> llm) {
        float[] vector = embedder.embed(question);
        Optional<Hit> hit = index.nearest(vector);
        if (hit.isPresent() && hit.get().distance() <= MAX_DISTANCE) {
            return hit.get().answer();
        }
        String fresh = llm.apply(question);
        index.put(question, vector, fresh, TTL_SECONDS);
        return fresh;
    }
}

